import React, { useState, useRef } from 'react';
import CustomHook from './CustomHook';

function Contacts() {
  const divs = useRef([]);
  const scrollTab = useRef();
  divs.current = [];

  const attachRef = (el) => {
    if (el && !divs.current.includes(el)) divs.current.push(el);
  };

  // ✅ Your updated contact info (GitHub removed)
  const [listContacts] = useState([
    {
      title: 'Phone',
      value: '+91 9079289874',
      href: 'tel:+919079289874',
      aria: 'Call Punit Gupta'
    },
    {
      title: 'Email',
      value: 'punitg505@gmail.com',
      href: 'mailto:punitg505@gmail.com',
      aria: 'Email Punit Gupta'
    },
    {
      title: 'LinkedIn',
      value: 'linkedin.com/in/punit-gupta-18a930255',
      href: 'https://www.linkedin.com/in/punit-gupta-18a930255',
      aria: 'Punit Gupta on LinkedIn'
    }
  ]);

  CustomHook(scrollTab, divs);

  return (
    <section
      className="contacts py-8"
      ref={scrollTab}
      aria-label="Contact Information"
    >
      <div className="title mb-4" ref={attachRef}>
        <h2 className="text-2xl font-semibold text-gray-900 dark:text-white">
          Contact
        </h2>
      </div>

      <p className="des text-gray-500 dark:text-gray-400 mb-6" ref={attachRef}>
        Feel free to reach out for opportunities, collaborations, or any queries.
      </p>

      <div
        className="list grid gap-4 sm:grid-cols-2"
        ref={attachRef}
        role="list"
      >
        {listContacts.map((item, idx) => (
          <div
            className="item p-4 rounded-md bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700"
            key={idx}
            role="listitem"
            ref={attachRef}
          >
            <h3 className="text-sm font-medium text-gray-700 dark:text-gray-300">
              {item.title}
            </h3>
            <div className="value mt-1">
              <a
                href={item.href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={item.aria}
                className="text-blue-600 dark:text-blue-400 hover:underline break-all"
              >
                {item.value}
              </a>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Contacts;
